&lt;li style=&quot;font-family: Helvetica, Arial, sans-serif; font-style: normal; font-weight: 400; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); background-color: transparent;&quot;&gt;Bilingual (Spanish and English) is required&lt;/span&gt;&lt;/li&gt;
