&lt;li style=&quot;font-family: Helvetica, Arial, sans-serif; font-style: normal; font-weight: 400; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); background-color: transparent;&quot;&gt;Thrives in an unstructured, fast-paced, and change-heavy environment&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: Helvetica, Arial, sans-serif; font-style: normal; font-weight: 400; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); background-color: transparent;&quot;&gt;Experience working with different countries of the LATAM regions preferred, but not required&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: Helvetica, Arial, sans-serif; font-style: normal; font-weight: 400; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); background-color: transparent;&quot;&gt;Experience working in Tech Touch Engagements &lt;/span&gt;&lt;/li&gt;
